const boss = new PgBoss(connectionString);
await boss.start();
await db.query("BEGIN");
await db.query("INSERT INTO orders(id, status) VALUES ($1, 'new')", [order.id]);
await boss.send("orders", order, { db });     // commits with the business write
await db.query("COMMIT");
await boss.work<Order>("orders", async ([job]) => {
  await gateway.deliver(job.data);            // ack happens when this resolves
});

